  cpf: "Informe um CPF v\xE1lido.",
  cnpj: "Informe um CNPJ v\xE1lido.",
  "cpf-cnpj": "Informe um CPF ou CNPJ v\xE1lido.",
  phone: "Informe um telefone v\xE1lido.",
  cep: "Informe um CEP v\xE1lido.",
  date: "Informe uma data v\xE1lida.",
  time: "Informe uma hora v\xE1lida.",
  minlength: "O valor informado \xE9 muito curto.",
  maxlength: "O valor informado excede o limite.",
  min: "O valor est\xE1 abaixo do m\xEDnimo permitido.",
