// src/js/components/popover.js
document.querySelectorAll("[data-org-popover]").forEach((popover) => {
  const trigger = popover.querySelector("[data-org-popover-toggle]");
  if (!trigger) {
    return;
  }
  trigger.addEventListener("click", (event) => {
    event.stopPropagation();
    const open = popover.classList.toggle("is-open");
    trigger.setAttribute(
      "aria-expanded",
      open ? "true" : "false"
    );
  });
  document.addEventListener("click", (event) => {
    if (!popover.contains(event.target)) {
      popover.classList.remove("is-open");
      trigger.setAttribute(
        "aria-expanded",
        "false"
      );
    }
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      popover.classList.remove("is-open");
      trigger.setAttribute(
        "aria-expanded",
        "false"
      );
    }
  });
});

// src/js/components/offcanvas.js
document.querySelectorAll("[data-org-offcanvas]").forEach((offcanvas) => {
  const id = offcanvas.id;
  const triggers = document.querySelectorAll(
    `[data-org-offcanvas-open="${id}"]`
  );
  const closes = offcanvas.querySelectorAll(
    "[data-org-offcanvas-close]"
  );
  const backdrop = offcanvas.querySelector(
    ".org-offcanvas-backdrop"
  );
  function open() {
    offcanvas.classList.add("is-open");
    offcanvas.setAttribute(
      "aria-hidden",
      "false"
    );
    document.body.style.overflow = "hidden";
  }
  function close3() {
    offcanvas.classList.remove("is-open");
    offcanvas.setAttribute(
      "aria-hidden",
      "true"
    );
    document.body.style.overflow = "";
  }
  triggers.forEach((trigger) => {
    trigger.addEventListener("click", open);
  });
  closes.forEach((button) => {
    button.addEventListener("click", close3);
  });
  if (backdrop) {
    backdrop.addEventListener("click", close3);
  }
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && offcanvas.classList.contains("is-open")) {
      close3();
    }
  });
});

// src/js/components/code.js
document.querySelectorAll("[data-org-code]").forEach((codeBlock) => {
  const tabs = codeBlock.querySelectorAll("[data-org-code-tab]");
  const panels = codeBlock.querySelectorAll("[data-org-code-panel]");
  const copyButton = codeBlock.querySelector("[data-org-code-copy]");
  tabs.forEach((tab) => {
    tab.addEventListener("click", () => {
      const target = tab.dataset.orgCodeTab;
      tabs.forEach((item) => {
        item.classList.toggle(
          "is-active",
          item === tab
        );
      });
      panels.forEach((panel) => {
        panel.hidden = panel.dataset.orgCodePanel !== target;
      });
    });
  });
  if (copyButton) {
    copyButton.addEventListener("click", async () => {
      const visiblePanel = Array.from(panels).find((panel) => !panel.hidden);
      if (!visiblePanel) {
        return;
      }
      const code = visiblePanel.querySelector("code");
      if (!code) {
        return;
      }
      try {
        await navigator.clipboard.writeText(
          code.textContent
        );
        const original = copyButton.textContent;
        copyButton.textContent = "Copiado!";
        window.setTimeout(() => {
          copyButton.textContent = original;
        }, 1500);
      } catch (error) {
        console.error(
          "Organic: n\xE3o foi poss\xEDvel copiar o c\xF3digo.",
          error
        );
      }
    });
  }
});

// src/js/components/stepper.js
document.querySelectorAll("[data-org-wizard]").forEach((wizard) => {
  const steps = Array.from(
    wizard.querySelectorAll("[data-org-step]")
  );
  const panels = Array.from(
    wizard.querySelectorAll("[data-org-step-panel]")
  );
  const nextButtons = wizard.querySelectorAll("[data-org-step-next]");
  const previousButtons = wizard.querySelectorAll("[data-org-step-prev]");
  let current = 0;
  function update() {
    steps.forEach((step, index) => {
      step.classList.toggle(
        "is-active",
        index === current
      );
      step.classList.toggle(
        "is-complete",
        index < current
      );
      if (index === current) {
        step.setAttribute(
          "aria-current",
          "step"
        );
      } else {
        step.removeAttribute("aria-current");
      }
    });
    panels.forEach((panel, index) => {
      panel.hidden = index !== current;
    });
  }
  nextButtons.forEach((button) => {
    button.addEventListener("click", () => {
      if (current >= steps.length - 1) {
        return;
      }
      current++;
      update();
    });
  });
  previousButtons.forEach((button) => {
    button.addEventListener("click", () => {
      if (current <= 0) {
        return;
      }
      current--;
      update();
    });
  });
  update();
});

