// src/js/components/kanban.js
document.addEventListener("DOMContentLoaded", () => document.querySelectorAll("[data-org-kanban]").forEach((board) => {
  let drag = null;
  board.querySelectorAll("[data-org-kanban-card]").forEach((card) => {
    card.draggable = true;
    card.addEventListener("dragstart", () => {
      drag = card;
      card.classList.add("is-dragging");
    });
    card.addEventListener("dragend", () => card.classList.remove("is-dragging"));
  });
  board.querySelectorAll("[data-org-kanban-list]").forEach((list) => {
    list.addEventListener("dragover", (e) => e.preventDefault());
    list.addEventListener("drop", () => {
      if (drag) {
        list.appendChild(drag);
        board.dispatchEvent(new CustomEvent("organic:kanban:move", { bubbles: true, detail: { card: drag, column: list.closest("[data-org-kanban-column]") } }));
      }
    });
  });
}));

// src/js/components/cookie.js
document.addEventListener("click", (e) => {
  const accept = e.target.closest("[data-org-cookie-accept]"), reject = e.target.closest("[data-org-cookie-reject]");
  if (!accept && !reject) return;
  const root2 = e.target.closest("[data-org-cookie]");
  if (root2) {
    root2.classList.add("is-hidden");
    root2.dispatchEvent(new CustomEvent("organic:cookie:change", { bubbles: true, detail: { accepted: !!accept } }));
  }
});
